public class InnerRouterInputRouterInputConfigurationFactory(Action<Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration>
{

    internal InnerRouterInputMediaConnectFlowRouterInputConfigurationFactory MediaConnectFlowFactory { get; set; }

    internal InnerRouterInputFailoverRouterInputConfigurationFactory FailoverFactory { get; set; }

    internal InnerRouterInputMergeRouterInputConfigurationFactory MergeFactory { get; set; }

    internal InnerRouterInputMediaLiveChannelRouterInputConfigurationFactory MediaLiveChannelFactory { get; set; }

    internal InnerRouterInputStandardRouterInputConfigurationFactory StandardFactory { get; set; }

    protected override Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration Create()
    {
        var routerInputConfigurationResult = CreateRouterInputConfiguration();
        factoryAction?.Invoke(routerInputConfigurationResult);

        return routerInputConfigurationResult;
    }

    private Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration CreateRouterInputConfiguration()
    {
        var routerInputConfigurationResult = new Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration();

        return routerInputConfigurationResult;
    }
    public override void CreateChildren(Humidifier.MediaConnect.RouterInputTypes.RouterInputConfiguration result)
    {
        base.CreateChildren(result);

        result.MediaConnectFlow ??= MediaConnectFlowFactory?.Build();
        result.Failover ??= FailoverFactory?.Build();
        result.Merge ??= MergeFactory?.Build();
        result.MediaLiveChannel ??= MediaLiveChannelFactory?.Build();
        result.Standard ??= StandardFactory?.Build();
    }

} // End Of Class

